import csv
from collections import defaultdict
tp='c778b459-3e21-5aaa-8431-ae20738126a6'
cool='3c51369d-a4f8-5e1a-8ff9-296dbd8b66f3'
tvals=defaultdict(dict); cvals=defaultdict(dict)
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        if row['timeseries_id']==tp: tvals[row['timestamp']]=float(row['value'])
        if row['timeseries_id']==cool: cvals[row['timestamp']]=float(row['value'])

def mean_dev(date):
    devs=[]
    for h in range(8,19):
        ts=date+'T%02d:00:00'%h
        if ts in tvals and ts in cvals:
            devs.append(tvals[ts]-cvals[ts])
    return sum(devs)/len(devs), len(devs)

for d in ('2018-04-02','2018-10-09'):
    mv,n=mean_dev(d)
    print(d,n,mv)
